5ea6\u3001DOM/\u53ef\u8bbf\u95ee\u6027\u6811\u89c2\u6d4b\u6e32\u67d3\u3001\u4efb\u52a1\u53c2\u6570\u91c7\u6837\u79cd\u5b50\u3001\u73af\u5883\u521d\u59cb\u72b6\u6001\u3001\u6700\u5927\u6b65\u6570\u622a\u65ad\u3001\u5e76\u53d1/\u7ad9\u70b9\u72b6\u6001\u6f02\u79fb\u3002\n\n\u4e09\u3001\u521d\u6b65\u5bf9\u7167\u5b9e\u9a8c\u7ed3\u6784\uff08\u62df\u63d0\u4ea4\u5b8c\u6574\u8bbe\u8ba1\u524d\u5f81\u6c42\u786e\u8ba4\uff09\n- \u4e24\u4e2a\u6838\u5fc3\u6761\u4ef6\uff08\u88ab\u8bd5\u5185\u914d\u5bf9\uff09\uff1a\n  A \u57fa\u7ebf\uff1a\u96f6\u6837\u672c\u201c\u4ec5\u884c\u52a8\u201d\u63d0\u793a\uff08ReAct-lite / direct action\uff0c\u5982 Kojima \u5f0f \"action-only\" \u5bf9\u7167\uff09\uff0c\u8f93\u51fa\u76f4\u63a5\u6620\u5c04\u4e3a\u52a8\u4f5c\u3002\n  B CoT\uff1a\u540c\u4e00\u63d0\u793a\u9aa8\u67b6 + \u663e\u5f0f\u601d\u8003\u6307\u4ee4\uff08\"think step by step before the action\"\uff09\u6216\u96f6\u6837\u672c CoT \u540e\u7f00\uff1b\u53ef\u9009 B'\uff1a\u5c11\u6837\u672c CoT\uff08\u9644\u63a8\u7406\u8f68\u8ff9\u793a\u4f8b\uff09\u3002\n- \u5173\u952e\u6df7\u6742\u63a7\u5236\uff08\u6700\u91cd\u8981\u7684\u4e00\u6761\uff09\uff1aCoT \u6761\u4ef6\u5f80\u5f80\u540c\u65f6\u589e\u52a0\u4e86\u63d0\u793a\u957f\u5ea6/\u793a\u4f8b\u6570\u91cf\u3002\u57fa\u7ebf\u987b\u505a\u201c\u7ed3\u6784\u7b49\u5316\u201d\u5bf9\u7167\u2014\u2014\u76f8\u540c\u793a\u4f8b\u69fd\u4f4d\u3001\u76f8\u8fd1 token \u9884\u7b97\u3001\u76f8\u540c\u52a8\u4f5c\u683c\u5f0f\u8bf4\u660e\uff0c\u53ea\u6539\u53d8\u201c\u662f\u5426\u751f\u6210\u663e\u5f0f\u63a8\u7406\u6587\u672c\u201d\uff0c\u5e76\u628a\u63a8\u7406\u6587\u672c\u4ece\u52a8\u4f5c\u89e3\u6790\u901a\u9053\u4e2d\u5265\u79bb\u3002\n- \u56fa\u5b9a\u53d8\u91cf\uff1a\u540c\u4e00\u6a21\u578b\u68c0\u67e5\u70b9\u4e0e API \u7248\u672c\u3001\u6e29\u5ea6\u4e0e\u89e3\u7801\u8bbe\u7f6e\uff08\u4e24\u79cd\u65b9\u6848\u89c1\u7b2c\u56db\u8282\uff09\u3001\u6700\u5927\u6b65\u6570\u3001\u89c2\u6d4b\u62bd\u8c61\uff08accessibility tree, AXTree \u6587\u672c\uff09\u3001\u52a8\u4f5c\u7a