import random, math

def sim_once(N, k, seed, p0_mean=0.30, lift_mean=0.35, lift_sd=0.45, corr=0.0):
    # corr: correlation between conditions' residual (0 -> fully shared task difficulty, residual independent)
    rng = random.Random(seed)
    d = []
    for i in range(N):
        # shared task difficulty (task random effect, shared by both conditions)
        logit0 = math.log(p0_mean/(1-p0_mean)) + rng.gauss(0, 0.8)
        p0 = 1/(1+math.exp(-logit0))
        p1 = 1/(1+math.exp(-(logit0 + rng.gauss(lift_mean, lift_sd))))
        s0 = sum(1 for _ in range(k) if rng.random()<p0)/k
        s1 = sum(1 for _ in range(k) if rng.random()<p1)/k
        d.append(s1-s0)
    m = sum(d)/N
    sd = math.sqrt(sum((x-m)**2 for x in d)/max(1,N-1))
    z = m/(sd/math.sqrt(N))
    # majority-vote dichotomy for McNemar-style discordance stats
    b=c=0
    return z, d

def power(N,k,sims=400,lift_mean=0.35):
    rej=0; sig=[]; disc=0; discN=0
    for s in range(sims):
        z,d = sim_once(N,k,1000+s,lift_mean=lift_mean)
